mapper.select:
SELECT p.id, p.student_id, s.entry_year, p.class_code, p.current_page, p.is_submitted, p.last_heartbeat,
       p.progress_detail,
       u.nick_name as student_name, s.student_no
FROM biz_guide_sheet_progress p
LEFT JOIN biz_student s ON p.student_id = s.student_id
LEFT JOIN sys_user u ON s.user_id = u.user_id
WHERE p.sheet_id = #{sheetId}
  AND s.entry_year = #{entryYear}
  AND p.class_code = #{classCode}
ORDER BY p.last_heartbeat DESC

SELECT id, sheet_id, student_id, class_code, current_page, is_submitted, last_heartbeat, progress_detail
FROM biz_guide_sheet_progress
WHERE sheet_id = #{sheetId} AND student_id = #{studentId}
